window.DOSIK=window.DOSIK||{};DOSIK["yc_sexcounsel"]={"1":[{"t":"table","title":"성 개념과 용어","head":["용어","뜻"],"rows":[["젠더(Gender)","사회·문화적 환경에서 후천적으로 학습하게 되는 성의 특성을 의미한다"],["게이","전체 동성애자들을 말하나, 현재는 남성 동성애자를 가리킨다"],["퀴어","성 소수자를 통칭하며 성소수자의 정체성을 드러낸다"],["양성성","사회심리적 성으로 성역할의 남성성과 여성성이 동시에 내재화되어 있는 경향을 말한다"],["쉬메일(she-male)","호르몬 투약 등으로 여성의 2차 성징을 갖추었으나 남성의 생식기를 가지고 있는 사람이다"],["커밍아웃","자신의 성정체성을 스스로 밝히는 것을 말한다"],["이반","동성애자들이 스스로를 일반인과 분리하여 지칭한다"]]}],"3":[{"t":"tree","title":"테스토스테론","root":"테스토스테론","branches":[["사춘기","사춘기의 성적변화는 내분비계 호르몬의 영향을 받는다"],["분비","여성과 남성의 부신에서 분비된다"],["작용","남녀의 신체적인 특징을 발달시킨다"],["폐경기","여성의 경우 분비량은 폐경기 후에 줄어든다"]]},{"t":"tree","title":"생식기의 구조","root":"생식기","branches":[["여성의 생식기","자궁, 난소, 난관 등이 있다"],["자궁경부","임신 유지 기능을 한다"],["난관","여성의 난관은 자궁과 난소를 연결한다"],["음핵(클리토리스)","남성의 귀두에 해당한다"],["생식세포","생식세포를 만드는 곳은 난소와 고환이다"],["사정관","전립선에서 요도로 내려오는 사정관은 2개이다"]]},{"t":"table","title":"성별 구별과 태동","head":["주제","내용"],"rows":[["성별 구별","출생 시 외부 생식기 구조로 생물학적 성의 구분이 어려울 때는 내부 생식기 구조로 성별을 구별한다"],["태동","임신 16주 내외로 태동을 느낀다"]]}],"4":[{"t":"table","title":"성역할 이론","head":["이론","내용"],"rows":[["사회학습이론","아동은 타인의 행동을 관찰하면서 성역할을 배운다"],["학습이론","부모가 아동에게 성에 맞는 성역할을 강화하고 가르친다"],["인지발달이론","아동은 자신의 성역할에 대한 개념을 형성한 후, 역할에 맞는 행동을 적극적으로 배워나간다"],["프로이트(S. Freud)","3～5세의 아동은 이성의 부모에게 근친적인 성적 느낌을 가진다고 주장했다 · 잠복기는 6～11세로 성적 관심이 잠재되어 있는 시기이다"]]},{"t":"tree","title":"성역할 사회화","root":"성역할 사회화","branches":[["젠더","사회문화적으로 학습된 성을 젠더(gender)라고 한다"],["성고정 관념","특정 사회에서 남성과 여성의 특징을 분류하는 것을 성고정 관념이라 한다"],["성역할 정체감","개인의 자아 속에 남성적 역할이나 여성적 역할과 연합된 특성을 수용하는 정도를 말한다 · 사회가 요구하고 기대하는 성역할에 동일시하는 정도에 따라 형성한다"],["부모","자녀의 옷, 놀이기구, 과제 부여 등으로 성역할 사회화를 한다"],["양성평등의식","성역할 사회화 과정에서 이루어진다"],["청소년","신체적 성장과 성호르몬의 분비가 급증하면서 남자와 여자로서의 성적감정을 키운다"]]}],"6":[{"t":"tree","title":"성소수자 상담자의 태도","root":"성소수자 상담","branches":[["공감","성소수자가 경험하는 사회적 고립을 공감한다"],["검토","성소수자에 대한 상담자의 태도와 감정, 신념을 검토한다"],["이해","성소수자가 직면할 수 있는 사회적 편견에 대해 이해한다 · 성소수자가 직면하고 있는 사회적 편견과 차별을 이해한다"],["성적 지향성","상담자의 성적 지향성을 내담자가 물을 때 알려줄 수 있다"]]},{"t":"tree","title":"동성애의 이해","root":"동성애","branches":[["성 표현","오늘날 동성애는 다양한 성 표현의 일부분이다"],["DSM-5","진단기준에서는 동성애를 이상 성행동이 아닌 성적 지향성의 문제로 간주한다"],["동성애 청소년","부모 및 주변 어른들의 정서적 지지를 필요로 한다 · 사회적 고립, 주의집중의 곤란, 낮은 자존감 등으로 심한 우울감을 경험하기도 한다"]]}],"7":[{"t":"tree","title":"사랑의 요소","root":"사랑","branches":[["열정","신체적 매력을 느끼게 하거나 성적 몰입을 일으키는 것과 관련된다"],["친밀감"],["헌신","사랑의 인지적 요소이다"]]},{"t":"def","term":"낭만적 사랑","text":"헌신만 남아 있는 상태"},{"t":"def","term":"자기확장이론","text":"인간의 확장이나 성장에 대한 욕구를 상대방을 통해 함께 이루어간다는 이론","ex":["아론(A. Aaron)이 제시하였다"]}],"8":[{"t":"tree","title":"성교육","root":"성교육","branches":[["목표","위험 성행동 예방은 청소년 성교육의 목표 중 하나이다"],["연령","청소년의 연령을 고려하여 실시하여야 한다"],["금욕-유일 접근법","피임과 콘돔에 대한 정보를 제한하고 성관계를 금지한다"],["포괄적 성교육(CSE)","2018년에 국제 성교육 가이드를 통해 제시한 기관은 유네스코이다"],["성행동","어떤 성행동도 자신의 의지에 부합해야 한다"]]}],"9":[{"t":"table","title":"피임 방법","head":["방법","내용"],"rows":[["콘돔","남성용이다 · 휴대가 간편하고, 가격이 저렴하고, 피임 성공률이 비교적 높다 · 1920년대에 라텍스 콘돔이 제작·사용되면서 피임 효과가 높아졌다"],["페미돔","여성용이다 · 성병감염 및 에이즈 예방에 탁월한 효과가 있다"],["정관수술","정관을 절단하는데, 수술 후에도 고환에서 정자는 계속 생산된다"],["월경주기법","다음 월경예정일로부터 평균 14일전이 배란 가능 기간이라는 가정에 기초한 방법이다"],["질외사정법","사정 이전에도 남성에게서 정액이 나올 수 있으므로 실패확률이 높다"],["자궁 내 장치","자궁 내 수정란의 착상을 방해하는 방법이다"]]},{"t":"table","title":"임신","head":["주제","내용"],"rows":[["오심·구토","임신 전반기에 흔한 증상이다"],["모자보건법 14조","여자 청소년이 남자 형제에 의해 임신된 경우 낙태가 가능하다"]]}],"10":[{"t":"table","title":"성매개감염","head":["감염","내용"],"rows":[["후천성면역결핍증(AIDS)","감염된 사람의 혈액을 통해 감염된다"],["매독","트레포네마 팔리둠이라는 균이 점막이나 피부를 통해 전염된다 · 피부나 점막에 증상이 나타난다"],["임질","온도 변화에 민감하여 고온건조 환경에서 사멸한다"],["클라미디아","여성의 난임을 초래할 수 있다"]]}],"11":[{"t":"tree","title":"성도착 증상","root":"성적 흥분","branches":[["아동에게 노출","사춘기 이전의 아동에게 성기를 노출함으로써 성적 흥분을 일으킨다"],["성숙한 개인에게 노출","신체적으로 성숙한 개인에게 성기를 노출함으로써 성적 흥분을 일으킨다"],["아동 대상 활동","사춘기 이전의 아동들을 대상으로 성적 활동을 한다"]]},{"t":"cause","title":"진단 기준","causes":["반복적이고 강렬한 성적 흥분이 성적 공상, 성적 충동 또는 성적 행동으로 발현된다"],"result":"적어도 6개월 이상 지속될 때 진단된다","effects":["노출증의 증상이 6개월 이상 지속될 경우에 진단된다"]},{"t":"cause","title":"성적 충동과 고통","causes":["성적 충동에 따른 행동"],"result":"사회적 영역에서 임상적으로 현저한 고통을 초래한다","effects":["현저한 고통이나 대인관계의 어려움을 초래한다"]},{"t":"def","term":"유병률","text":"남성이 여성보다 더 높은 유병률을 보인다"}],"12":[{"t":"tree","title":"성 상담자의 윤리","root":"성 상담자","branches":[["법적 권리","내담자의 법적권리를 침해하거나 차별해서는 안된다"],["복지","내담자의 복지, 권리 및 최선의 이익을 보호해야 한다"],["역량","상담개입 역량을 갖추어야 한다 · 자신의 역량과 한계를 인지하고 지속적으로 교육에 참여해야 한다"],["피해자","피해자의 잘못이 아님을 알려준다 · 피해자는 비난받을 사람이 아님을 확인시켜 주도록 한다"],["의뢰","성 피해 트라우마를 겪는 청소년을 상담하는데 한계가 나타날 경우에는 다른 상담자에게 상담을 의뢰한다 · 성 피해를 당한 친구의 딸을 돕기 위해 다른 상담자에게 전문 상담을 의뢰한다"],["동성애 청소년","동성애로 고민을 하는 청소년 내담자의 성 지향성을 존중하고 공감한다"]]}],"13":[{"t":"table","title":"온라인 상담","head":["방식","특징"],"rows":[["게시판 상담","익명성을 보장할 수 있어 솔직한 대화나 감정 표현이 가능하다"],["채팅 상담","실시간 상담으로 얼굴이 보이지 않아 두려움에서 벗어날 수 있다"],["이메일","장기간 상담이 지속가능하고, 내담자가 자신의 성고민을 정리해 볼 수 있는 기회를 제공한다"],["비언어적 메시지","이해하기 힘들 수 있다"]]},{"t":"def","term":"상담 종결","text":"내담자가 새로운 행동을 학습하고 통합할 수 있을 때 성공적으로 종결될 가능성이 높다"},{"t":"tree","title":"성교 통증 상담","root":"성교 통증","branches":[["원인","통증의 원인은 신체적 또는 심리적 원인이 있을 수 있어요"],["성폭력 경험","사춘기 때 성폭력 경험이 관련될 수 있어요"],["치료","의학적으로 통증 장애를 치료할 수 있어요"],["연구 결과","여성 환자의 일부가 성교 통증을 호소해요"]]}],"14":[{"t":"tree","title":"성폭력 위기개입","root":"성폭력 위기개입","branches":[["지지","피해자는 지지적인 관계 형성이 필요하다"],["상담자","안정에 관심을 가지고 안전한 상태를 확인한다 · 법적인 도움을 받을 수 있도록 도와야 한다"],["증거","피해자는 샤워를 하거나 몸을 씻어서 자신의 몸에 남아있는 증거를 없애지 말아야 한다"],["가족 가해자","가해자가 가족인 경우 가해자와 피해자가 같은 집에 거주하지 않도록 한다"]]}],"15":[{"t":"tree","title":"상담 종결 단계","root":"상담 종결","branches":[["이별 감정","상담 종결에 대한 이별 감정을 다룬다"],["성과 평가","상담 성과를 내담자와 평가하고 서로 공유한다"],["미해결 과제","상담 종결 후에도 미해결 과제가 있을 수 있음을 알리고 대처할 수 있도록 조치한다"],["문제 해결 정도","내담자가 호소한 문제의 해결 정도를 살펴본 후 마무리한다"]]},{"t":"tree","title":"성피해자 집단상담","root":"집단상담","branches":[["동질집단","동질집단으로 구성하는 것이 더욱 효과적이다 · 집단원들은 동일 경험을 공유하고 있어 신뢰형성 및 동맹이 용이하다"],["치료효과","성피해 경험을 가진 집단원들은 자신들의 피해경험을 공유하여 치료효과를 나타낼 수 있다 · 심리적 고통을 서로 이야기하면서 동질감을 느끼게 된다"],["나눌 기회","성피해자들은 낮은 자존감, 친밀관계 형성의 어려움과 성생활 곤란 등을 집단상담 시에 나눌 수 있는 기회를 갖는다"],["왜곡된 생각","성폭력 피해에 대한 왜곡된 생각을 수정할 수 있다"],["비밀유지","집단에서 성폭력 피해사실에 대한 비밀유지를 중단하기도 한다"]]},{"t":"def","term":"직면의 수위","text":"상담자는 내담자의 피해정도 및 자아강도에 따라 외상에 대한 직면의 수위를 조절해야 한다"}],"16":[{"t":"tree","title":"아동 성학대 상담","root":"아동 성학대 상담","branches":[["칭찬","아동에게 성피해 사실을 밝힌 것은 용기있는 행동이라고 칭찬해준다"],["아동의 잘못","어떤 상황에서든지 성폭력은 아동의 잘못이 아니라는 것을 확인시켜 준다"],["의료적 서비스","외형적으로 드러난 신체적 상처가 없다 할지라도 의료적 서비스를 받도록 한다"],["안전","아동이 안전하게 느끼도록 돕는다"]]}],"17":[{"t":"tree","title":"성폭력 가해자 상담","root":"가해자 상담","branches":[["인정과 책임","성폭력 가해자로서 가해행동을 인정한다 · 가해자가 가해행동을 인정하고 책임을 수용하도록 한다"],["공감","피해자의 고통과 상처에 대해 공감적으로 이해하도록 한다"],["행동 변화","부적절한 성행동을 확인하고 제거하도록 한다 · 성폭력이 재발되지 않도록 방지한다 · 부적절한 성적 행동을 중단한다"],["태도 변화","가해자의 폭력에 대한 태도나 가치관을 변화시킨다"],["기술 훈련","분노 조절 및 사회적 상호작용 기술 훈련을 통해 사회에 적응하도록 한다 · 대인관계에서 상호 존중하는 방법을 배운다 · 자신의 감정을 지각하고 표현할 능력을 증가시킨다"],["신뢰","자신과 타인에 대한 신뢰감을 회복한다"]]},{"t":"def","term":"가해자","text":"자기가 원하는 것과 하고 싶은 것만 하고 용서를 기대한다"}],"18":[{"t":"tree","title":"스토킹","root":"스토킹","branches":[["정의","다른 사람을 지속적으로 따라다니거나 사생활을 침범하는 등 괴롭히는 행위를 말한다"],["데이트폭력","연관성이 있다"],["성격장애 가해자","경계선ㆍ자기애적ㆍ편집성 성격장애가 주로 발견된다"],["피해자","법적 도움을 받기 위한 녹음이나 증거 등을 수집하는 것이 좋다"]]},{"t":"tree","title":"스토킹 상담 사례","root":"A군 사례","branches":[["지속적인 행동","A군이 그렇게 지속적으로 하는 행동은 스토킹 범죄가 될 수 있어요"],["점차 심각","스토킹 행위는 점차 심각해지기 때문에 여기서 정리하는 것이 좋을 것 같은데요"],["학교 앞","A군이 학교 앞에서 계속 기다리는 것도 스토킹 행위가 될 수 있어요"],["신고","그 여학생이 1366이나 112에 신고할 수 있어요"]]},{"t":"tree","title":"데이트 성폭력","root":"데이트 성폭력","branches":[["연인사이","본인의 의사에 반하여 일어난 성행위는 성폭력이다"],["청소년","이성교제에서도 데이트 성폭력의 위험이 있다"],["유형","상대방의 감시와 간섭과 같은 정신적인 스트레스와 불안을 일으키는 행동도 포함된다"],["스토킹","연인사이에서의 스토킹도 데이트 성폭력이 될 수 있다"]]}],"19":[{"t":"tree","title":"사이버 성폭력","root":"사이버 성폭력","branches":[["정의","당사자가 인지하지 못한 상황에 음란물이 유포되었다면 사이버 성폭력에 해당한다"],["유형","언어 성폭력, 영상 성폭력의 유형 등으로 나눌 수 있다"],["피해","피해자에게 성적 수치심이나 모멸감 등의 실제적 피해를 유발한다"],["성적 메시지","문자, 이미지, 동영상 등을 통한 일방적인 성적 메시지를 보내는 행위가 포함된다"],["협박 도구","사귀던 친구와 주고받은 성적 동영상을 협박 도구로 이용하는 사례도 많다"],["스마트폰","친구의 스마트폰 요금을 대납하고 있어도 그 스마트폰에 저장된 내용을 사용할 권리는 없다"]]},{"t":"tree","title":"디지털 성범죄","root":"아동ㆍ청소년대상 디지털 성범죄","branches":[["수사","신분비공개수사를 할 수 있다 · 긴급 신분위장수사를 할 수 있다"],["성착취물","영상매체에서 19세 미만인 사람이 자위행위를 하는 내용이 있으면 아동ㆍ청소년 성착취물에 해당한다"],["처벌","아동ㆍ청소년 성착취물임을 알면서 이를 소지ㆍ시청한 자는 법률에 의해 처벌할 수 있다"]]},{"t":"tree","title":"성문화 교육","root":"성문화","branches":[["음란매체","음란매체를 많이 경험할수록 왜곡된 성 지식이 증가한다"],["찾아가는 성교육","여성가족부에서는 청소년성문화센터를 통해 학교와 연계한 찾아가는 성교육을 실시하고 있다"]]}]};
