(window.TNQ=window.TNQ||[]).push({"terms":{"젠더":{"d":"생물학적 성과 달리 사회·문화적 환경에서 후천적으로 학습하게 되는 성의 특성.","r":["성고정 관념","성역할 사회화"]},"성정체성":{"d":"자신을 어떤 성으로 인식하는지에 대한 스스로의 규정.","r":[]},"성소수자":{"d":"성적 지향이나 성정체성이 사회의 다수와 다른 사람.","r":["성적 지향성"]},"성적 지향성":{"d":"정서적·성적 매력을 어떤 성에게 느끼는지에 대한 방향.","r":["동성애","성소수자"]},"동성애":{"d":"같은 성에게 정서적·성적으로 끌리는 성적 지향.","r":["성적 지향성"]},"성고정 관념":{"d":"특정 사회에서 남성과 여성의 특징을 분류해 놓은 고정된 생각.","r":["젠더"]},"성역할 사회화":{"d":"사회가 기대하는 성역할을 부모 등을 통해 학습해 가는 과정.","r":["젠더"]},"잠복기":{"d":"프로이트가 말한 6∼11세 시기로 성적 관심이 잠재되어 있다.","r":[]},"착상":{"d":"수정란이 자궁 안에 자리를 잡는 일.","r":[]},"사정관":{"d":"전립선에서 요도로 내려오는 관으로 2개이다.","r":[]},"폐경기":{"d":"여성의 월경이 멈추는 시기로 이후 테스토스테론 분비량이 줄어든다.","r":[]},"태동":{"d":"임신 중 태아의 움직임으로 임신 16주 내외에 느낀다.","r":[]},"노출증":{"d":"성기를 노출하며 성적 흥분을 일으키는 성도착 증상으로 6개월 이상 지속될 때 진단한다.","r":[]},"유병률":{"d":"특정 시점에 질환을 가진 사람이 인구에서 차지하는 비율.","r":[]},"신분비공개수사":{"d":"수사관이 신분을 밝히지 않고 하는 수사로 디지털 성범죄에서 할 수 있다.","r":["긴급 신분위장수사"]},"긴급 신분위장수사":{"d":"급박한 경우 신분을 위장해 하는 수사.","r":["신분비공개수사"]},"성착취물":{"d":"아동·청소년이 성적 행위를 하는 내용의 영상·화상 등으로 소지·시청도 처벌된다.","r":[]},"사이버 성폭력":{"d":"당사자가 모르게 음란물을 퍼뜨리거나 일방적인 성적 메시지를 보내는 등 온라인에서 일어나는 성폭력.","r":["데이트 성폭력"]},"데이트 성폭력":{"d":"연인 사이에서 본인 의사에 반해 일어난 성행위나 감시·간섭 같은 행동.","r":["스토킹","사이버 성폭력"]},"스토킹":{"d":"다른 사람을 지속적으로 따라다니거나 사생활을 침범하며 괴롭히는 행위.","r":["데이트 성폭력"]},"동질집단":{"d":"비슷한 경험을 가진 사람끼리 구성한 집단.","r":[]},"직면":{"d":"내담자가 피해 온 문제나 외상을 마주하게 하는 상담 기법.","r":["자아강도","외상"]},"자아강도":{"d":"스트레스와 외상을 견디는 자아의 힘.","r":["직면"]},"외상":{"d":"정신에 큰 상처를 남기는 충격적인 경험.","r":["직면"]},"비밀유지":{"d":"상담에서 알게 된 내용을 밖으로 알리지 않는 의무.","r":[]},"의뢰":{"d":"상담자가 한계에 이르렀을 때 다른 전문 상담자에게 사례를 넘기는 일.","r":[]}},"notes":{"1920년대에 라텍스 콘돔이 제작·사용되면서 피임 효과가 높아졌다":"1920년대에 라텍스 소재 콘돔이 쓰이기 시작하며 피임 효과가 개선되었습니다.","2018년에 국제 성교육 가이드를 통해 제시한 기관은 유네스코이다":"포괄적 성교육은 유네스코가 2018년 국제 성교육 가이드로 제시한 접근입니다.","3～5세의 아동은 이성의 부모에게 근친적인 성적 느낌을 가진다고 주장했다":"프로이트는 3~5세 아동이 이성 부모에게 근친적인 성적 느낌을 갖는다고 주장했습니다.","A군이 그렇게 지속적으로 하는 행동은 스토킹 범죄가 될 수 있어요":"한 사람을 계속 따라다니는 A군의 행동은 스토킹 범죄에 해당할 수 있어요.","A군이 학교 앞에서 계속 기다리는 것도 스토킹 행위가 될 수 있어요":"학교 앞에서 상대를 계속 기다리는 행동도 스토킹으로 볼 수 있어요.","가해자가 가족인 경우 가해자와 피해자가 같은 집에 거주하지 않도록 한다":"가족이 가해자라면 재피해를 막으려고 피해자와 한집에 살지 않게 분리합니다.","가해자가 가해행동을 인정하고 책임을 수용하도록 한다":"인정에서 더 나아가 자기 행동의 책임을 받아들이도록 이끕니다.","가해자의 폭력에 대한 태도나 가치관을 변화시킨다":"폭력을 대하는 가해자의 태도와 가치관을 바꾸는 것도 목표입니다.","감염된 사람의 혈액을 통해 감염된다":"AIDS는 감염자의 혈액이 몸에 들어올 때 전파됩니다.","개인의 자아 속에 남성적 역할이나 여성적 역할과 연합된 특성을 수용하는 정도를 말한다":"성역할 정체감은 남성적·여성적 역할과 짝지어진 특성을 자신의 자아에 받아들인 정도입니다.","경계선ㆍ자기애적ㆍ편집성 성격장애가 주로 발견된다":"스토킹 가해자에게서는 경계선, 자기애적, 편집성 성격장애가 주로 발견됩니다.","그 여학생이 1366이나 112에 신고할 수 있어요":"피해 학생은 1366이나 112에 전화해서 신고할 수 있어요.","긴급 신분위장수사를 할 수 있다":"급박할 때는 신분을 위장해 수사하는 긴급 신분위장수사도 할 수 있습니다.","남녀의 신체적인 특징을 발달시킨다":"이 호르몬은 남녀 각각의 신체적 특징이 발달하도록 작용합니다.","남성이 여성보다 더 높은 유병률을 보인다":"성도착 증상은 남성이 여성보다 많이 나타납니다.","내담자가 새로운 행동을 학습하고 통합할 수 있을 때 성공적으로 종결될 가능성이 높다":"내담자가 새 행동을 익혀 자기 삶에 통합하면 상담이 성공적으로 종결될 가능성이 큽니다.","내담자가 호소한 문제의 해결 정도를 살펴본 후 마무리한다":"호소 문제가 어느 정도 풀렸는지 따져 본 다음 상담을 마무리합니다.","내담자의 법적권리를 침해하거나 차별해서는 안된다":"상담자는 내담자의 법적 권리를 해치거나 내담자를 차별하면 안 됩니다.","내담자의 복지, 권리 및 최선의 이익을 보호해야 한다":"내담자의 복지와 권리와 최선의 이익을 지키는 것이 상담자의 책임입니다.","노출증의 증상이 6개월 이상 지속될 경우에 진단된다":"노출증은 증상이 6개월 이상 이어질 때 진단합니다.","다른 사람을 지속적으로 따라다니거나 사생활을 침범하는 등 괴롭히는 행위를 말한다":"스토킹은 상대를 계속 따라다니거나 사생활을 침범하며 괴롭히는 행위입니다.","다음 월경예정일로부터 평균 14일전이 배란 가능 기간이라는 가정에 기초한 방법이다":"월경주기법은 다음 월경 예정일에서 평균 14일 전에 배란한다고 가정해 계산합니다.","당사자가 인지하지 못한 상황에 음란물이 유포되었다면 사이버 성폭력에 해당한다":"당사자가 모르는 사이에 음란물이 퍼졌다면 사이버 성폭력입니다.","대인관계에서 상호 존중하는 방법을 배운다":"관계에서 서로를 존중하는 방식을 가해자가 새로 익힙니다.","동성애로 고민을 하는 청소년 내담자의 성 지향성을 존중하고 공감한다":"동성애 문제로 고민하는 청소년에게는 평가하지 않고 그 지향을 인정하며 마음을 헤아립니다.","동성애자들이 스스로를 일반인과 분리하여 지칭한다":"이반은 동성애자들이 일반인과 자신들을 구분해 부르는 호칭입니다.","동질집단으로 구성하는 것이 더욱 효과적이다":"성피해자 집단상담은 비슷한 경험을 한 사람끼리 묶는 동질집단이 효과적입니다.","문자, 이미지, 동영상 등을 통한 일방적인 성적 메시지를 보내는 행위가 포함된다":"상대가 원하지 않는데 문자나 이미지, 동영상으로 성적 메시지를 보내는 것도 포함됩니다.","반복적이고 강렬한 성적 흥분이 성적 공상, 성적 충동 또는 성적 행동으로 발현된다":"성도착은 강렬한 성적 흥분이 공상이나 충동, 행동으로 되풀이해 나타나는 상태입니다.","법적 도움을 받기 위한 녹음이나 증거 등을 수집하는 것이 좋다":"스토킹 피해자는 법적 도움을 받을 수 있게 녹음이나 증거를 모아 두면 유리합니다.","법적인 도움을 받을 수 있도록 도와야 한다":"피해자가 법적 도움을 받을 수 있게 연결해 주는 것도 상담자의 몫입니다.","본인의 의사에 반하여 일어난 성행위는 성폭력이다":"연인 사이여도 본인이 원하지 않았다면 그 성행위는 성폭력입니다.","부모가 아동에게 성에 맞는 성역할을 강화하고 가르친다":"학습이론은 부모가 성에 맞는 행동을 강화하고 가르쳐서 성역할이 형성된다고 봅니다.","부모 및 주변 어른들의 정서적 지지를 필요로 한다":"동성애 청소년에게는 부모와 주변 어른의 정서적 지지가 필요합니다.","부적절한 성적 행동을 중단한다":"부적절한 성적 행동을 멈추는 것이 행동 변화의 한 부분입니다.","부적절한 성행동을 확인하고 제거하도록 한다":"가해자의 부적절한 성행동을 파악해서 없애는 것이 행동 변화의 목표입니다.","분노 조절 및 사회적 상호작용 기술 훈련을 통해 사회에 적응하도록 한다":"분노 조절과 사회적 상호작용 기술 훈련으로 사회에 적응하도록 돕습니다.","사귀던 친구와 주고받은 성적 동영상을 협박 도구로 이용하는 사례도 많다":"사귀던 사이에 오간 성적 동영상이 협박 도구로 악용되는 일이 많습니다.","사정 이전에도 남성에게서 정액이 나올 수 있으므로 실패확률이 높다":"사정 전에도 정액이 흘러나올 수 있어서 질외사정법은 피임에 실패하기 쉽습니다.","사춘기 때 성폭력 경험이 관련될 수 있어요":"사춘기에 겪은 성폭력 경험이 성교 통증과 연결되는 경우가 있어요.","사춘기의 성적변화는 내분비계 호르몬의 영향을 받는다":"사춘기에 나타나는 성적 변화의 배경에는 내분비계 호르몬이 있습니다.","사춘기 이전의 아동들을 대상으로 성적 활동을 한다":"사춘기 이전 아동을 상대로 하는 성적 활동에 집착하는 증상이 소아성애장애입니다.","사춘기 이전의 아동에게 성기를 노출함으로써 성적 흥분을 일으킨다":"사춘기 이전 아동에게 성기를 드러내며 성적 흥분을 얻는 형태입니다.","사회가 요구하고 기대하는 성역할에 동일시하는 정도에 따라 형성한다":"성역할 정체감은 사회가 기대하는 성역할에 얼마나 자신을 동일시하는지에 따라 형성됩니다.","사회문화적으로 학습된 성을 젠더(gender)라고 한다":"생물학적 성과 구별되는 개념으로, 사회문화를 통해 배워서 갖게 된 성을 젠더라고 합니다.","사회·문화적 환경에서 후천적으로 학습하게 되는 성의 특성을 의미한다":"젠더는 타고난 생물학적 성이 아니라 사회와 문화 속에서 배우며 형성되는 성의 특성입니다.","사회심리적 성으로 성역할의 남성성과 여성성이 동시에 내재화되어 있는 경향을 말한다":"양성성은 한 사람 안에 남성성과 여성성이 함께 내면화되어 있는 사회심리적 성의 경향입니다.","사회적 고립, 주의집중의 곤란, 낮은 자존감 등으로 심한 우울감을 경험하기도 한다":"고립, 집중 곤란, 낮은 자존감이 겹치면 동성애 청소년이 심한 우울감을 겪을 수 있습니다.","사회적 영역에서 임상적으로 현저한 고통을 초래한다":"사회생활 영역에서 임상적으로 뚜렷한 고통이 생겨야 합니다.","상담개입 역량을 갖추어야 한다":"성 상담자는 상담에 개입할 수 있는 실력을 갖추어야 합니다.","상담 성과를 내담자와 평가하고 서로 공유한다":"상담으로 얻은 성과를 내담자와 함께 평가하고 서로 나눕니다.","상담자는 내담자의 피해정도 및 자아강도에 따라 외상에 대한 직면의 수위를 조절해야 한다":"외상을 직면시키는 강도는 내담자의 피해 정도와 자아강도에 맞춰 조절해야 합니다.","상담자의 성적 지향성을 내담자가 물을 때 알려줄 수 있다":"내담자가 상담자의 성적 지향성을 물으면 알려 줄 수 있습니다.","상담 종결에 대한 이별 감정을 다룬다":"종결 단계에서는 상담이 끝나는 데서 오는 이별 감정을 함께 다룹니다.","상담 종결 후에도 미해결 과제가 있을 수 있음을 알리고 대처할 수 있도록 조치한다":"종결 뒤에도 남을 수 있는 미해결 과제를 미리 알리고 스스로 대처하도록 돕습니다.","상대방의 감시와 간섭과 같은 정신적인 스트레스와 불안을 일으키는 행동도 포함된다":"신체 접촉이 없어도 감시와 간섭으로 불안을 일으키면 데이트 성폭력 유형에 듭니다.","생식세포를 만드는 곳은 난소와 고환이다":"난자는 난소에서, 정자는 고환에서 만들어지므로 두 곳이 생식세포를 만드는 곳입니다.","성병감염 및 에이즈 예방에 탁월한 효과가 있다":"페미돔은 여성이 착용해서 성병과 에이즈 감염을 막는 데 효과가 큽니다.","성소수자가 경험하는 사회적 고립을 공감한다":"상담자는 성소수자가 겪는 사회적 고립을 함께 느끼고 헤아려야 합니다.","성소수자가 직면하고 있는 사회적 편견과 차별을 이해한다":"편견뿐 아니라 실제로 겪는 차별까지 이해하는 것이 상담자의 태도입니다.","성소수자가 직면할 수 있는 사회적 편견에 대해 이해한다":"성소수자가 마주칠 수 있는 사회적 편견을 상담자가 알고 있어야 합니다.","성 소수자를 통칭하며 성소수자의 정체성을 드러낸다":"퀴어는 성소수자를 두루 이르는 말이며 그들의 정체성을 드러내는 데 쓰입니다.","성소수자에 대한 상담자의 태도와 감정, 신념을 검토한다":"상담자는 먼저 성소수자에 대한 자기 태도와 감정, 신념을 돌아보아야 합니다.","성역할 사회화 과정에서 이루어진다":"양성평등의식도 성역할 사회화를 거치는 가운데 길러집니다.","성폭력 가해자로서 가해행동을 인정한다":"가해자 상담에서는 자신이 가해자라는 사실과 가해행동을 인정하게 합니다.","성폭력이 재발되지 않도록 방지한다":"재발 방지가 상담의 목표에 들어 있습니다.","성폭력 피해에 대한 왜곡된 생각을 수정할 수 있다":"집단에서 다른 사람의 이야기를 들으며 피해에 대한 왜곡된 생각을 바로잡을 수 있습니다.","성피해 경험을 가진 집단원들은 자신들의 피해경험을 공유하여 치료효과를 나타낼 수 있다":"피해 경험을 서로 나누는 것만으로 치료 효과가 생길 수 있습니다.","성 피해를 당한 친구의 딸을 돕기 위해 다른 상담자에게 전문 상담을 의뢰한다":"친구의 딸처럼 가까운 사이의 피해자는 직접 맡지 않고 다른 상담자에게 의뢰합니다.","성피해자들은 낮은 자존감, 친밀관계 형성의 어려움과 성생활 곤란 등을 집단상담 시에 나눌 수 있는 기회를 갖는다":"낮은 자존감과 친밀관계의 어려움, 성생활 곤란을 집단에서 털어놓을 기회를 얻습니다.","성 피해 트라우마를 겪는 청소년을 상담하는데 한계가 나타날 경우에는 다른 상담자에게 상담을 의뢰한다":"감당하기 어려운 한계가 보이면 다른 전문 상담자에게 넘기는 의뢰가 윤리에 맞습니다.","스토킹 행위는 점차 심각해지기 때문에 여기서 정리하는 것이 좋을 것 같은데요":"스토킹은 갈수록 심해지는 경향이 있어서 일찍 끊어 내는 쪽이 나아요.","신분비공개수사를 할 수 있다":"디지털 성범죄 수사에서는 경찰이 신분을 밝히지 않고 하는 신분비공개수사가 가능합니다.","신체적 매력을 느끼게 하거나 성적 몰입을 일으키는 것과 관련된다":"사랑의 요소 중 열정은 신체적 매력과 성적 몰입을 일으키는 성분입니다.","신체적 성장과 성호르몬의 분비가 급증하면서 남자와 여자로서의 성적감정을 키운다":"청소년기에는 신체가 자라고 성호르몬이 급증해 남자와 여자로서의 성적 감정이 커집니다.","신체적으로 성숙한 개인에게 성기를 노출함으로써 성적 흥분을 일으킨다":"성숙한 사람에게 성기를 보이며 흥분하는 형태로 노출 대상이 앞의 경우와 다릅니다.","실시간 상담으로 얼굴이 보이지 않아 두려움에서 벗어날 수 있다":"채팅 상담은 실시간으로 이야기하되 얼굴이 보이지 않아 두려움이 줄어듭니다.","심리적 고통을 서로 이야기하면서 동질감을 느끼게 된다":"고통을 서로 털어놓다 보면 나만 그런 게 아니라는 동질감을 느낍니다.","아동ㆍ청소년 성착취물임을 알면서 이를 소지ㆍ시청한 자는 법률에 의해 처벌할 수 있다":"성착취물인 줄 알면서 갖고 있거나 본 사람도 처벌 대상이 됩니다.","아동에게 성피해 사실을 밝힌 것은 용기있는 행동이라고 칭찬해준다":"아동이 피해 사실을 털어놓은 것을 용기 있는 행동으로 인정해 칭찬합니다.","아동은 자신의 성역할에 대한 개념을 형성한 후, 역할에 맞는 행동을 적극적으로 배워나간다":"인지발달이론은 아동이 성역할 개념을 먼저 만든 다음 그에 맞는 행동을 스스로 배운다고 봅니다.","아동은 타인의 행동을 관찰하면서 성역할을 배운다":"사회학습이론은 아동이 주변 사람의 행동을 보고 따라 하며 성역할을 익힌다고 설명합니다.","아동이 안전하게 느끼도록 돕는다":"아동이 지금 안전하다고 느끼도록 상담자가 환경을 마련합니다.","아론(A. Aaron)이 제시하였다":"자기확장이론을 내놓은 학자는 아론입니다.","안정에 관심을 가지고 안전한 상태를 확인한다":"상담자는 피해자의 안정을 살피고 지금 안전한 상태인지 확인합니다.","어떤 상황에서든지 성폭력은 아동의 잘못이 아니라는 것을 확인시켜 준다":"어떤 경우에도 성폭력의 책임은 아동에게 없다는 점을 분명히 알려 줍니다.","어떤 성행동도 자신의 의지에 부합해야 한다":"성교육은 성행동이 언제나 자기 의지에 맞아야 한다는 점을 가르칩니다.","언어 성폭력, 영상 성폭력의 유형 등으로 나눌 수 있다":"사이버 성폭력은 말로 하는 언어 성폭력과 영상 성폭력 등으로 나눕니다.","여성가족부에서는 청소년성문화센터를 통해 학교와 연계한 찾아가는 성교육을 실시하고 있다":"청소년성문화센터가 학교와 이어져 직접 찾아가서 하는 성교육을 합니다.","여성과 남성의 부신에서 분비된다":"테스토스테론은 성별에 관계없이 여성과 남성 모두의 부신에서 분비됩니다.","여성의 경우 분비량은 폐경기 후에 줄어든다":"여성은 폐경기가 지나면 분비량이 감소합니다.","여성의 난관은 자궁과 난소를 연결한다":"난관은 난소와 자궁 사이를 이어 주는 통로입니다.","여성의 난임을 초래할 수 있다":"클라미디아에 감염되면 여성이 임신하기 어려운 난임으로 이어질 수 있습니다.","여성 환자의 일부가 성교 통증을 호소해요":"연구에서 여성 환자 가운데 일부가 성교할 때 통증을 겪는다고 나타났어요.","여자 청소년이 남자 형제에 의해 임신된 경우 낙태가 가능하다":"남자 형제로 인한 임신처럼 혈족 사이에서 임신이 된 때에는 낙태가 법에서 허용됩니다.","연인사이에서의 스토킹도 데이트 성폭력이 될 수 있다":"사귀는 사이의 스토킹도 데이트 성폭력에 해당할 수 있습니다.","영상매체에서 19세 미만인 사람이 자위행위를 하는 내용이 있으면 아동ㆍ청소년 성착취물에 해당한다":"19세 미만이 자위행위를 하는 내용이 담긴 영상이면 아동·청소년 성착취물로 봅니다.","오늘날 동성애는 다양한 성 표현의 일부분이다":"동성애는 다양한 성 표현 가운데 하나로 이해되는 추세입니다.","온도 변화에 민감하여 고온건조 환경에서 사멸한다":"임질균은 온도 변화에 약해서 뜨겁고 마른 환경에서는 죽습니다.","외형적으로 드러난 신체적 상처가 없다 할지라도 의료적 서비스를 받도록 한다":"겉으로 다친 곳이 없어 보여도 의료적 서비스를 받게 합니다.","위험 성행동 예방은 청소년 성교육의 목표 중 하나이다":"청소년 성교육은 위험한 성행동을 예방하는 것을 목표로 삼습니다.","음란매체를 많이 경험할수록 왜곡된 성 지식이 증가한다":"음란매체를 많이 접할수록 잘못된 성 지식을 갖게 되는 정도가 커집니다.","의학적으로 통증 장애를 치료할 수 있어요":"통증 장애는 의학적 치료가 가능한 문제예요.","이성교제에서도 데이트 성폭력의 위험이 있다":"청소년의 이성교제에도 데이트 성폭력이 생길 위험이 있습니다.","익명성을 보장할 수 있어 솔직한 대화나 감정 표현이 가능하다":"게시판 상담은 익명이 지켜져 속마음을 솔직하게 말하기 쉽습니다.","인간의 확장이나 성장에 대한 욕구를 상대방을 통해 함께 이루어간다는 이론":"자기확장이론은 성장하려는 욕구를 연인과 함께 채워 간다고 설명합니다.","임신 16주 내외로 태동을 느낀다":"산모는 임신 16주 전후부터 태아의 움직임인 태동을 느낍니다.","임신 전반기에 흔한 증상이다":"오심과 구토는 임신의 전반기에 흔히 나타납니다.","자궁, 난소, 난관 등이 있다":"여성 생식기는 자궁, 난소, 난관 등으로 이루어집니다.","자궁 내 수정란의 착상을 방해하는 방법이다":"자궁 내 장치는 수정란이 자궁에 자리 잡는 착상을 막아 피임합니다.","자기가 원하는 것과 하고 싶은 것만 하고 용서를 기대한다":"가해자의 특성으로 자기 욕구만 따르면서도 나중에 용서받으리라 기대합니다.","자녀의 옷, 놀이기구, 과제 부여 등으로 성역할 사회화를 한다":"부모는 자녀에게 입히는 옷과 주는 놀이기구, 맡기는 과제를 통해 성역할을 가르칩니다.","자신과 타인에 대한 신뢰감을 회복한다":"자신과 타인을 믿는 마음을 되찾도록 합니다.","자신의 감정을 지각하고 표현할 능력을 증가시킨다":"자기 감정을 알아차리고 표현하는 능력을 키웁니다.","자신의 성정체성을 스스로 밝히는 것을 말한다":"커밍아웃은 자기의 성정체성을 다른 사람에게 스스로 알리는 일입니다.","자신의 역량과 한계를 인지하고 지속적으로 교육에 참여해야 한다":"상담자는 자기 능력의 한계를 알고 꾸준히 교육을 받아야 합니다.","잠복기는 6～11세로 성적 관심이 잠재되어 있는 시기이다":"잠복기는 6~11세에 성적 관심이 겉으로 드러나지 않고 잠재되어 있는 시기입니다.","장기간 상담이 지속가능하고, 내담자가 자신의 성고민을 정리해 볼 수 있는 기회를 제공한다":"이메일 상담은 오래 이어 갈 수 있고 내담자가 성 고민을 글로 정리해 볼 기회를 줍니다.","적어도 6개월 이상 지속될 때 진단된다":"일회성이 아니라 최소 6개월은 계속되어야 진단 요건을 충족합니다.","전립선에서 요도로 내려오는 사정관은 2개이다":"사정관은 전립선에서 요도로 이어지며 좌우 한 쌍인 2개입니다.","전체 동성애자들을 말하나, 현재는 남성 동성애자를 가리킨다":"게이는 본래 동성애자 전체를 가리켰으나 지금은 남성 동성애자를 뜻합니다.","정관을 절단하는데, 수술 후에도 고환에서 정자는 계속 생산된다":"정관수술은 정자의 이동 통로만 끊을 뿐 고환의 정자 생산은 그대로입니다.","진단기준에서는 동성애를 이상 성행동이 아닌 성적 지향성의 문제로 간주한다":"진단기준은 동성애를 이상 성행동이 아니라 성적 지향성의 문제로 봅니다.","집단에서 성폭력 피해사실에 대한 비밀유지를 중단하기도 한다":"집단 상황에서 피해 사실의 비밀유지가 중단되기도 한다는 점을 짚습니다.","집단원들은 동일 경험을 공유하고 있어 신뢰형성 및 동맹이 용이하다":"같은 경험을 공유하는 사이라서 서로 믿고 동맹을 맺기가 쉽습니다.","청소년의 연령을 고려하여 실시하여야 한다":"성교육은 대상 청소년의 나이에 맞추어 내용과 방식을 정해야 합니다.","출생 시 외부 생식기 구조로 생물학적 성의 구분이 어려울 때는 내부 생식기 구조로 성별을 구별한다":"겉모습으로 성별 판별이 어려운 신생아는 속에 있는 내부 생식기 구조를 보고 구별합니다.","친구의 스마트폰 요금을 대납하고 있어도 그 스마트폰에 저장된 내용을 사용할 권리는 없다":"요금을 대신 내 주는 것은 기기 안에 저장된 내용을 쓸 권리가 되지 못합니다.","통증의 원인은 신체적 또는 심리적 원인이 있을 수 있어요":"성교 통증은 몸의 문제일 수도 있고 마음의 문제일 수도 있어요.","트레포네마 팔리둠이라는 균이 점막이나 피부를 통해 전염된다":"매독은 트레포네마 팔리둠균이 점막이나 피부로 들어와 전염되는 병입니다.","특정 사회에서 남성과 여성의 특징을 분류하는 것을 성고정 관념이라 한다":"성고정 관념은 한 사회가 남성과 여성의 특징을 정해진 틀로 나누어 보는 생각입니다.","피부나 점막에 증상이 나타난다":"매독에 걸리면 감염 부위인 피부와 점막에 증상이 보입니다.","피임과 콘돔에 대한 정보를 제한하고 성관계를 금지한다":"금욕-유일 접근법은 피임 정보를 줄이고 성관계 자체를 하지 말라고 가르칩니다.","피해자는 비난받을 사람이 아님을 확인시켜 주도록 한다":"피해자가 비난의 대상이 아니라는 점을 상담에서 분명하게 해 줍니다.","피해자는 샤워를 하거나 몸을 씻어서 자신의 몸에 남아있는 증거를 없애지 말아야 한다":"씻으면 몸에 남은 증거가 사라지므로 피해 직후에는 샤워를 하지 않아야 합니다.","피해자는 지지적인 관계 형성이 필요하다":"위기에 놓인 피해자에게는 자신을 받아 주는 지지적인 관계가 필요합니다.","피해자에게 성적 수치심이나 모멸감 등의 실제적 피해를 유발한다":"사이버 성폭력도 피해자에게 성적 수치심과 모멸감이라는 실제 피해를 줍니다.","피해자의 고통과 상처에 대해 공감적으로 이해하도록 한다":"피해자가 겪는 고통과 상처를 가해자가 공감하며 이해하도록 돕습니다.","피해자의 잘못이 아님을 알려준다":"피해자에게는 일어난 일이 피해자의 잘못이 아니라고 분명히 전해 줍니다.","현저한 고통이나 대인관계의 어려움을 초래한다":"성도착 증상이 심한 고통이나 대인관계의 어려움을 일으키는 것도 진단 요건입니다.","호르몬 투약 등으로 여성의 2차 성징을 갖추었으나 남성의 생식기를 가지고 있는 사람이다":"쉬메일은 호르몬 투약 등으로 2차 성징은 여성처럼 갖추었으나 생식기는 남성인 사람을 가리킵니다.","휴대가 간편하고, 가격이 저렴하고, 피임 성공률이 비교적 높다":"콘돔은 들고 다니기 쉽고 값이 싸며 피임 성공률도 비교적 높습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
